class Solution { public int countHillValley(int[] nums){List<Integer> values=new ArrayList<>();for(int value:nums)if(values.isEmpty()||values.get(values.size()-1)!=value)values.add(value);int answer=0;for(int i=1;i+1<values.size();i++)if(values.get(i)>values.get(i-1)&&values.get(i)>values.get(i+1)||values.get(i)<values.get(i-1)&&values.get(i)<values.get(i+1))answer++;return answer;} }
